+		fmt.Fprintf(w, "    %s\n", command)
+	}
+}
+
+func encodeTrailResumeContextJSON(w io.Writer, ctx trailResumeContext) error {
+	enc := json.NewEncoder(w)
+	enc.SetIndent("", "  ")
+	if err := enc.Encode(ctx); err != nil {
+		return fmt.Errorf("encode trail resume JSON: %w", err)
+	}
+	return nil
