	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to list sessions: %w", err)
	}
	states = filterResumableSessions(states)

	repo, err := openRepository(ctx)
	if err != nil {
		items := make([]resumableSession, 0, len(states))
